template<typename OuterA2, typename... InnerAllocs>
OuterAlloc(OuterA2&& outerAlloc, InnerAllocs&&... innerAllocs) noexcept {
    // Forward outerAlloc to base class constructor
    BaseClass(std::forward<OuterA2>(outerAlloc));
    // Initialize inner allocators with perfect forwarding
    inner = { std::forward<InnerAllocs>(innerAllocs)... };
}
